winter_wyvern_arctic_burn = class({})

function winter_wyvern_arctic_burn:GetCooldown(nLevel)
    local cooldown = self.BaseClass.GetCooldown(self, nLevel)

    if self:GetCaster():HasScepter() then
        return 0
    else
        return cooldown
    end
end

function winter_wyvern_arctic_burn:GetBehavior()
    local caster = self:GetCaster()
    if caster:HasScepter() == true then
        return DOTA_ABILITY_BEHAVIOR_TOGGLE + DOTA_ABILITY_BEHAVIOR_IMMEDIATE
    else
        return DOTA_ABILITY_BEHAVIOR_NO_TARGET + DOTA_ABILITY_BEHAVIOR_IMMEDIATE
    end
end

function winter_wyvern_arctic_burn:OnSpellStart()
    if IsServer() then
        local caster  = self:GetCaster();
        local ability = self;
        winter_wyvern_arctic_burn:ToggleOn(caster, ability);
    end
end

function winter_wyvern_arctic_burn:OnToggle()
    if IsServer() then
        local toggle  = self:GetToggleState();
        local caster  = self:GetCaster();
        local ability = self;

        if toggle == true then
            winter_wyvern_arctic_burn:ToggleOn(caster, ability);
        else
            caster:RemoveModifierByName("modifier_winter_wyvern_arctic_burn_flight");
            caster:RemoveModifierByName("m_modifier_winter_wyvern_arctic_burn");
        end
    end
end

function winter_wyvern_arctic_burn:ToggleOn(caster, ability)
    local duration = ability:GetSpecialValueFor("duration");

    -- This is to prevent Scepter pickup/refresh abuse into a 0 mana infinite duration modifier
    caster:RemoveModifierByName("modifier_winter_wyvern_arctic_burn_flight");
    caster:RemoveModifierByName("m_modifier_winter_wyvern_arctic_burn");

    if caster:HasScepter() == true then
        duration = -1;
    end

    caster:EmitSound("Hero_Winter_Wyvern.ArcticBurn.Cast");

    caster:AddNewModifier(caster, ability, "modifier_winter_wyvern_arctic_burn_flight", { duration = duration });
    local start_flight_particle = ParticleManager:CreateParticle(
        "particles/units/heroes/hero_winter_wyvern/wyvern_arctic_burn_start.vpcf", PATTACH_ABSORIGIN, caster);
    ParticleManager:SetParticleControl(start_flight_particle, 0, caster:GetAbsOrigin());
    ParticleManager:ReleaseParticleIndex(start_flight_particle);

    local arctic_burn_modifier = caster:AddNewModifier(caster, ability, "m_modifier_winter_wyvern_arctic_burn",
        { duration = duration });
end

function winter_wyvern_arctic_burn:OnInventoryContentsChanged()
    local caster = self:GetCaster()

    if not caster:HasScepter() then
        if caster:HasModifier("modifier_winter_wyvern_arctic_burn_flight") and caster:FindModifierByName("modifier_winter_wyvern_arctic_burn_flight"):GetDuration() == -1 then
            caster:RemoveModifierByName("modifier_winter_wyvern_arctic_burn_flight")
        end

        if caster:HasModifier("m_modifier_winter_wyvern_arctic_burn") and caster:FindModifierByName("m_modifier_winter_wyvern_arctic_burn"):GetDuration() == -1 then
            caster:RemoveModifierByName("m_modifier_winter_wyvern_arctic_burn")
            self:ToggleAbility()
        end
    end
end

