m_modifier_winter_wyvern_arctic_burn = class({})
function m_modifier_winter_wyvern_arctic_burn:IsHidden() return true end

function m_modifier_winter_wyvern_arctic_burn:DeclareFunctions()
    decFuncs = {
        MODIFIER_EVENT_ON_ATTACK_LANDED,
    }

    return decFuncs
end

function m_modifier_winter_wyvern_arctic_burn:OnAttackLanded(keys)
    if IsServer() then
        local caster = self:GetCaster();
        if keys.attacker == caster and not keys.target:IsBuilding() then
            local damage_duration = self:GetAbility():GetSpecialValueFor("damage_duration");
            if (not keys.target:HasModifier("m_modifier_winter_wyvern_arctic_burn_slow") or caster:HasScepter() == true) and not keys.target:IsMagicImmune()
            then
                local ability = self:GetAbility();

                keys.target:AddNewModifier(caster, self:GetAbility(),
                    "m_modifier_winter_wyvern_arctic_burn_slow", { duration = damage_duration });

                EmitSoundOn("Hero_Winter_Wyvern.ArcticBurn.projectileImpact", keys.target);


                if RandomInt(1, 100) > 80 then
                    caster:EmitSound("winter_wyvern_winwyv_articburn_0" .. RandomInt(1, 4));
                end
            end
        end
    end
end

