m_modifier_winter_wyvern_arctic_burn_slow = class({})
function m_modifier_winter_wyvern_arctic_burn_slow:IsHidden() return false end

function m_modifier_winter_wyvern_arctic_burn_slow:OnCreated()
    if IsServer() then
        self.ability               = self:GetAbility();
        self.health_dmg_conversion = self.ability:GetSpecialValueFor("percent_damage") / 100;
        self.tick_rate             = self.ability:GetSpecialValueFor("tick_rate")
        self.slow_hit_particle     = ParticleManager:CreateParticle(
            "particles/units/heroes/hero_winter_wyvern/wyvern_arctic_burn_slow.vpcf", PATTACH_ABSORIGIN_FOLLOW,
            self:GetParent());
        ParticleManager:SetParticleControl(self.slow_hit_particle, 0, self:GetParent():GetAbsOrigin());

        self:StartIntervalThink(self.tick_rate);
    end
end

function m_modifier_winter_wyvern_arctic_burn_slow:OnIntervalThink()
    local parent         = self:GetParent();
    local caster         = self:GetCaster();
    local current_health = parent:GetHealth();
    local im_level       = GameRules:GetCustomGameDifficulty()
    if im_level >= 1 then
        current_health = parent:GetMaxHealth();
    end
    local damage             = current_health * self.health_dmg_conversion * self.tick_rate;

    local damage_type        = DAMAGE_TYPE_MAGICAL;

    local damage_table       = {};
    damage_table.attacker    = caster;
    damage_table.ability     = self.ability;
    damage_table.damage_type = damage_type;
    damage_table.damage      = damage;
    damage_table.victim      = parent;
    ApplyDamage(damage_table);
    SendOverheadEventMessage(nil, OVERHEAD_ALERT_BONUS_SPELL_DAMAGE, parent, damage, nil);
end

function m_modifier_winter_wyvern_arctic_burn_slow:DeclareFunctions()
    return {
        MODIFIER_PROPERTY_MOVESPEED_BONUS_PERCENTAGE,
    }
end

function m_modifier_winter_wyvern_arctic_burn_slow:GetModifierMoveSpeedBonus_Percentage()
    return -self:GetAbility():GetSpecialValueFor("move_slow")
end

function m_modifier_winter_wyvern_arctic_burn_slow:OnRemoved()
    if IsServer() then
        ParticleManager:DestroyParticle(self.slow_hit_particle, false);
    end
end
